function reply(body: unknown): typeof fetch {
  return async () => Response.json(body);
}
const signal = () => new AbortController().signal;
const funder = {
  id: funderId,
  name: "Exact Funder",
  kind: "Funder",
  funder_kind: "Company",
  match_source: { kind: "name" },
};

for (const match_source of [
  undefined,
  null,
  {},
  { kind: "other" },
  { kind: "alias", name: "" },
  { kind: "alias", name: "   " },
  { kind: "alias" },
]) {
  test(`search rejects malformed match source ${JSON.stringify(match_source)}`, async () => {
    await expect(
      searchEntities(
        "Exact",
        signal(),
        reply({ entities: [funder] }),
        "http://api",
      ),
    ).resolves.toHaveLength(1);
    await expect(
      searchEntities(
        "Exact",
        signal(),
        reply({ entities: [{ ...funder, match_source }] }),
        "http://api",
      ),
    ).rejects.toThrow("unexpected match source");
  });
}

test("search rejects alias provenance for an MP", async () => {
  const mp = {
    id: "1",
    name: "West",
    kind: "MP",
    funder_kind: null,
    match_source: { kind: "name" },
  };
  await expect(
    searchEntities("West", signal(), reply({ entities: [mp] }), "http://api"),
  ).resolves.toHaveLength(1);
  await expect(
    searchEntities(
      "West",
      signal(),
      reply({
        entities: [
          { ...mp, match_source: { kind: "alias", name: "West Midlands" } },
        ],
      }),
      "http://api",
    ),
  ).rejects.toThrow("unexpected MP identity");
});

const funderRoute = {
  kind: "funder",
  id: funderId,
  view: "summary",
} satisfies Parameters<typeof loadDetails>[0];
for (const [name, body] of [
  ["missing declarations", { ...funderDetails, declarations: undefined }],
  [
    "invalid source timestamp",
    {
      ...funderDetails,
      declarations: [
        {
          member,
          declaration: {
            ...funderDetails.declarations[0].declaration,
            registered_at: "broken",
          },
        },
      ],
    },
  ],
  [
    "missing currency total",
    {
      ...funderDetails,
      currencies: funderDetails.currencies.map((group, index) =>
        index === 1 ? { ...group, amount: undefined } : group,
      ),
    },
  ],
  ...[null, "Exact Funder", ["Exact Funder", 42]].map((aliases) => [
    `recorded names ${JSON.stringify(aliases)}`,
    { ...funderDetails, funder: { ...funderDetails.funder, aliases } },
  ]),
]) {
  test(`details rejects ${name}`, async () => {
    expect(
      (
        await loadDetails(
          funderRoute,
          signal(),
          reply(funderDetails),
          "http://api",
        )
      ).kind,
    ).toBe("funder");
    expect(
      await loadDetails(funderRoute, signal(), reply(body), "http://api"),
    ).toEqual({
      kind: "error",
      message: "Details returned an unexpected response. Try again.",
    });
  });
}

test("details rejects a mismatched member identity", async () => {
  const route = {
    kind: "member",
    id: "1",
    view: "summary",
  } satisfies Parameters<typeof loadDetails>[0];
  expect(
    (await loadDetails(route, signal(), reply(memberDetails), "http://api"))
      .kind,
  ).toBe("member");
  expect(
    (
      await loadDetails(
        route,
        signal(),
        reply({ ...memberDetails, member: { ...member, id: "2" } }),
        "http://api",
      )
    ).kind,
  ).toBe("error");
});

test("details preserves decimal strings and rejects a numeric nested party amount", async () => {
  const valid = await loadDetails(
    funderRoute,
    signal(),
    reply(funderDetails),
    "http://api",
  );
  expect(valid.kind).toBe("funder");
  if (valid.kind !== "funder") throw new Error("expected funder details");
  expect(valid.details.currencies[1].parties[0].amount).toBe(
    "18014398509481986.246913578",
  );
  const body = {
    ...funderDetails,
    currencies: funderDetails.currencies.map((group, index) =>
      index === 1
        ? {
            ...group,
            parties: group.parties.map((party, partyIndex) =>
              partyIndex === 0 ? { ...party, amount: 9007199254740993 } : party,
            ),
          }
        : group,
    ),
  };
  expect(
    (await loadDetails(funderRoute, signal(), reply(body), "http://api")).kind,
  ).toBe("error");
});
import { registrationTimeline } from "../src/lib/registration-timeline";
import { expect, test } from "@playwright/test";
import { summarizeMember, formatPounds } from "../src/lib/member-summary";
import {
  categoryBars,
  type MemberDetails,
  type MemberDeclaration,
  type FundingEntry,
} from "../src/lib/entity-details";

function entry(
  amount: string | null,
  currency: string | null = "GBP",
): FundingEntry {
  return { amount, currency, funder: null, paymentType: null };
}
function declaration(
  registeredAt: string | null,
  entries: FundingEntry[],
  categoryName = "Employment and earnings",
  categoryId = 12,
): MemberDeclaration {
  return { registeredAt, entries, categoryName, categoryId, sourceId: 1 };
}
function details(declarations: MemberDeclaration[]): MemberDetails {
  return {
    member: {
      id: "1",
      name: "Example",
      partyName: "",
      membershipFrom: "",
      isCurrentCommons: true,
    },
    declarations,
    summary: {
      declaredTotals: {
        currentTermStart: "2024-07-09T00:00:00Z",
        currentTerm: {
          amount: "225.45",
          declarationCount: 7,
          incomplete: true,
        },
        historical: { amount: "333", declarationCount: 9, incomplete: true },
      },
      currencies: [
        {
          currency: "EUR",
          amount: "999",
          categories: [],
          entryCount: 1,
          unknownAmountCount: 0,
        },
        {
          currency: "GBP",
          amount: "123.45",
          categories: [],
          entryCount: 1,
          unknownAmountCount: 0,
        },
      ],
      entryCount: 1,
      unknownCurrencyCount: 0,
      firstRegisteredAt: null,
      lastRegisteredAt: null,
      undatedDeclarationCount: 0,
    },
  };
}

