  await backend.route("**/api/funders/*", (route) =>
    route.fulfill({
      json: {
        ...funderDetails,
        currencies: [],
        entry_count: 0,
        unknown_currency_count: 0,
      },
    }),
  );
  await page.goto("/members/1");
